const originalShowAuth=showAuth;
const interestOptions=['TikTok One','TikTok Market Scope','Commercial Partnership Solutions','Collaboration Plus','Konsultasi VIP','Layanan berbayar Buzzo','Learning Center','Kelas','Kelas Offline'];
let registerStep=1,registerData={};
showAuth=function(type){if(type!=='register')return originalShowAuth(type);registerStep=1;registerData={};renderRegisterWizard()};
function wizardField(name,label,placeholder='',type='text',help=''){return `<label>${label}${help?`<small>${help}</small>`:''}<input name="${name}" type="${type}" value="${escHtml(registerData[name]||'')}" placeholder="${placeholder}" required></label>`}
function renderRegisterWizard(){closeModal();const box=authBox();box.hidden=false;document.body.classList.add('auth-open');const summary=`<div class="wizard-intro"><span class="wizard-tag">CARA BERGABUNG</span><h1>Registrasi, hubungkan akun, bertumbuh.</h1><p>Ikuti tiga langkah ini untuk bergabung dengan program Buzzo.</p><div class="wizard-info"><b>01 · Kode undangan</b><p>Masukkan kode undangan yang kamu terima dari tim.</p></div><div class="wizard-info"><b>02 · Data bisnis dan toko</b><p>Siapkan informasi bisnis, akun iklan, dan toko TikTok Shop.</p></div><div class="wizard-info"><b>03 · Data akun</b><p>Isi nama, nomor WhatsApp, email, dan password.</p></div><small>SIAPKAN SEBELUM MULAI<br>Nama bisnis · Advertiser ID · Nama dan link toko · Shop Code · Email · Nomor WhatsApp</small></div>`;
const progress=`<nav class="wizard-steps" aria-label="Langkah pendaftaran">${['KODE','TOKO','AKUN'].map((x,i)=>`<span class="${registerStep===i+1?'current':registerStep>i+1?'done':''}"><b>${registerStep>i+1?'✓':i+1}</b>${x}</span>`).join('')}</nav>`;
const choices=interestOptions.map((name,i)=>`<label class="wizard-choice"><input type="checkbox" name="interests" value="${escHtml(name)}" ${(registerData.interests||[]).includes(name)?'checked':''}> ${escHtml(name)}</label>`).join('');
let form=registerStep===1?`<h2>Kode undangan</h2><p>Masukkan kode undangan dari event atau tim Buzzo untuk melanjutkan.</p><form id="wizard-code"><label>Kode undangan<input name="invite_code" autocomplete="off" value="${escHtml(registerData.invite_code||'')}" placeholder="Masukkan kode undangan" required></label><button class="cta" type="submit">Validasi & lanjut ↗</button><p class="sb-message" role="status"></p></form>`:registerStep===2?`<h2>Data bisnis dan toko</h2><p>Data ini membantu tim memahami kondisi iklan dan toko kamu.</p><form id="wizard-shop">${wizardField('business_name','Nama bisnis','PT Maju Jaya Sejahtera','text','Nama usaha atau organisasi peserta, bukan nama toko TikTok Shop.')}${wizardField('advertiser_id','Advertiser ID','ID akun iklan utama')}${wizardField('shop_name','Nama Toko TikTok Shop','Masukkan nama toko Anda')}${wizardField('shop_url','Link TikTok Shop','https://www.tiktok.com/...','url')}${wizardField('shop_code','Shop Code','Masukkan Shop Code')}<label>Apakah kamu tertarik menggunakan layanan berbayar Buzzo?<select name="agency_interest" required><option value="">Pilih jawaban</option>${['Ya, saya tertarik','Saya ingin melihat hasil terlebih dahulu','Tidak, saya belum tertarik'].map(x=>`<option ${registerData.agency_interest===x?'selected':''}>${x}</option>`).join('')}</select></label><fieldset class="wizard-interests"><legend>Minat program <small>· boleh pilih lebih dari satu</small></legend>${choices}</fieldset><div class="wizard-actions"><button type="button" class="action" data-wizard-back>Kembali</button><button class="cta" type="submit">Lanjut ke data akun ↗</button></div></form>`:`<h2>Data akun</h2><p>Isi data untuk membuat akun dan mengakses portal member.</p><form id="sb-register">${['invite_code','business_name','advertiser_id','shop_name','shop_url','shop_code','agency_interest'].map(k=>`<input type="hidden" name="${k}" value="${escHtml(registerData[k]||'')}">`).join('')}<input type="hidden" name="interests" value="${escHtml(JSON.stringify(registerData.interests||[]))}">${wizardField('full_name','Nama lengkap','Masukkan nama lengkap')}${wizardField('whatsapp','Nomor WhatsApp','08...','tel')}${wizardField('email','Email','nama@email.com','email')}<label>Password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><label>Konfirmasi password<input name="password_confirm" type="password" minlength="8" autocomplete="new-password" required></label><div class="wizard-actions"><button type="button" class="action" data-wizard-back>Kembali</button><button class="cta" type="submit">Daftar ↗</button></div><p class="sb-message" role="status"></p></form>`;
box.innerHTML=`<header><button class="action" data-sb-close>← Kembali ke landing page</button><strong>BUZZO · REGISTRATION</strong></header><div class="auth-grid wizard-grid"><section>${summary}</section><section class="auth-form wizard-form">${progress}${form}<p class="wizard-privacy">Data pendaftaran diproses untuk keperluan program.</p></section></div>`;window.scrollTo(0,0)}
document.addEventListener('submit',e=>{if(e.target.id==='wizard-code'){e.preventDefault();e.stopImmediatePropagation();let code=new FormData(e.target).get('invite_code').trim().toUpperCase();if(code!=='JAKARTANOV'){e.target.querySelector('.sb-message').textContent='Kode undangan tidak valid. Silakan coba lagi.';return}registerData.invite_code=code;registerStep=2;renderRegisterWizard()}else if(e.target.id==='wizard-shop'){e.preventDefault();e.stopImmediatePropagation();const data=new FormData(e.target);for(const k of ['business_name','advertiser_id','shop_name','shop_url','shop_code','agency_interest'])registerData[k]=data.get(k);registerData.interests=data.getAll('interests');registerStep=3;renderRegisterWizard()}},true);
document.addEventListener('click',e=>{if(!e.target.closest('[data-wizard-back]'))return;const form=e.target.closest('form');if(form?.id==='sb-register'){const d=new FormData(form);for(const k of ['full_name','whatsapp','email'])registerData[k]=d.get(k)}registerStep=Math.max(1,registerStep-1);renderRegisterWizard()},true);
